func testDeployment(t *testing.T) InitialDeployment {
	t.Helper()
	deployment, err := NewDeploymentIdentity(InitialDeployment{
		Region: oci.RegionGRU, PlacementDatabaseID: "0000000000HX30KC7N7WJ1ZFC8", PartitionID: "00000000003ZJEV7X3HYJENEYG",
		LiveS3: LiveS3Target{Bucket: "alpha-live", Region: "sa-saopaulo-1",
			Endpoint:      "https://alpha.compat.objectstorage.sa-saopaulo-1.oci.customer-oci.com",
			Credential:    oci.SecretVersionReference{SecretOCID: "ocid1.vaultsecret.oc1.sa-saopaulo-1.alpha", VersionNumber: 1},
			NativeOCIRoot: &NativeOCIRoot{Namespace: "alpha"}},
		Members: [2]DeploymentMember{
			{SeatID: "000000000082AXF7GZQT1D126Y", ServerName: "permanent-a.terrabase.internal", FailureDomain: "FAULT-DOMAIN-1", PrivateIP: "10.0.0.21"},
			{SeatID: "0000000000XG8SBD7XGE97V28G", ServerName: "elastic-gru.terrabase.internal", FailureDomain: "FAULT-DOMAIN-2", PrivateIP: "10.0.0.22"},
		},
		ReplicationPort: 7422, ClientPort: 8080, ManagedRuntimeRoot: "/srv/ts-managed",
	}, 1)
	if err != nil {
		t.Fatal(err)
	}
	return deployment
}

func testHostProfile() placement.ManagedHostProfile {
	return placement.ManagedHostProfile{Region: oci.RegionGRU,
		Compute:            placement.ComputeTuple{Shape: "VM.Standard.A1.Flex", WholeOCPUs: 1, MemoryInGBs: 6},
		ProcessMemoryBytes: 4 << 30, MemoryHeadroomBytes: 1 << 30, CgroupMemoryMaxBytes: 4 << 30,
		SystemReserveBytes: 1 << 30, AllocatableMemoryBytes: 4 << 30}
}

func NewDeploymentIdentity(deployment InitialDeployment, collections int) (InitialDeployment, error) {
	if collections < 1 || collections > 16 {
		return InitialDeployment{}, errors.New("a managed deployment needs 1 to 16 collections")
	}
	var token [16]byte
	if _, err := rand.Read(token[:]); err != nil {
		return InitialDeployment{}, err
	}
	cluster := hex.EncodeToString(token[:])
	deployment.Scope = AuthorityScope{ClusterID: cluster,
		TenantID: entityid.New(), DatabaseID: entityid.New(), ShardID: 1, Epoch: 1}
	for index := range deployment.Members {
		if _, err := rand.Read(token[:]); err != nil {
			return InitialDeployment{}, err
		}
		incarnation := hex.EncodeToString(token[:])
		deployment.Members[index].MemberID = entityid.New()
		deployment.Members[index].Incarnation = incarnation
		deployment.Members[index].FileSystemUUID = uuid.New().String()
	}
	deployment.CollectionIDs = make([]string, collections)
	for index := range deployment.CollectionIDs {
		deployment.CollectionIDs[index] = entityid.New()
	}
	return deployment, nil
}

// Validate checks every operator and identity pin before any signing step.
func (deployment InitialDeployment) Validate() error {
	seats, err := placement.RegionSeatIDs(deployment.Region)
	if err != nil {
		return err
	}
	ociRegion, err := deployment.Region.OCIRegion()
	if err != nil {
		return err
	}
	if !entityid.Valid(deployment.PlacementDatabaseID) || !entityid.Valid(deployment.PartitionID) {
		return errors.New("placement database and partition IDs must be canonical uppercase ULIDs")
	}
	if err := deployment.LiveS3.Validate(); err != nil {
		return err
	}
	if deployment.LiveS3.Region != ociRegion {
		return errors.New("live S3 target region differs from the placement region")
	}
	if deployment.ReplicationPort == 0 || deployment.ClientPort == 0 || deployment.ReplicationPort == deployment.ClientPort {
		return errors.New("replication and client ports must be distinct and nonzero")
	}
	if _, err := canonicalID(deployment.Scope.TenantID); err != nil {
		return err
	}
	if _, err := canonicalID(deployment.Scope.DatabaseID); err != nil {
		return err
	}
	if !lowerHexIdentity(deployment.Scope.ClusterID) || deployment.Scope.ShardID == 0 || deployment.Scope.Epoch != 1 {
		return errors.New("deployment shard scope is invalid")
	}
	if len(deployment.CollectionIDs) == 0 {
		return errors.New("deployment needs at least one collection")
	}
	for _, id := range deployment.CollectionIDs {
		if _, err := canonicalID(id); err != nil {
			return err
		}
	}
	for index, member := range deployment.Members {
		ip, err := netip.ParseAddr(member.PrivateIP)
		if member.SeatID != seats[index] || !validServerName(member.ServerName) ||
			!validFailureDomain(member.FailureDomain) || err != nil || !ip.Is4() || !validPrivateIP(member.PrivateIP) ||
			!lowerHexIdentity(member.Incarnation) || !validFileSystemUUID(member.FileSystemUUID) {
			return fmt.Errorf("deployment member %d is incomplete or out of seat order", index)
		}
		if _, err := canonicalID(member.MemberID); err != nil {
			return err
		}
	}
	first, second := deployment.Members[0], deployment.Members[1]
	if first.MemberID == second.MemberID || first.PrivateIP == second.PrivateIP ||
		first.FailureDomain == second.FailureDomain || first.ServerName == second.ServerName ||
		first.FileSystemUUID == second.FileSystemUUID || first.Incarnation == second.Incarnation {
		return errors.New("deployment members repeat an identity, address or fault domain")
	}
	if len(deployment.ManagedRuntimeRoot) > 54 {
		return errors.New("managed runtime root exceeds the placement path bound")
	}
	for index := range deployment.Members {
		if _, err := host.ManagedMountPath(deployment.ManagedRuntimeRoot, deployment.binding(index)); err != nil {
			return fmt.Errorf("managed runtime root: %w", err)
		}
	}
	return nil
}

func (deployment InitialDeployment) binding(index int) host.ManagedMemberBinding {
	member := deployment.Members[index]
	return host.ManagedMemberBinding{Scope: host.MemberScope{
		ClusterID: deployment.Scope.ClusterID, TenantID: deployment.Scope.TenantID,
		DatabaseID: deployment.Scope.DatabaseID, ShardID: deployment.Scope.ShardID,
		MemberID: member.MemberID, Incarnation: member.Incarnation,
	}, HostAttempt: 1}
}

// DraftSpec returns the unsigned generation-one material spec. Members are
// ordered by member ID (TerraBase authority order); catalogs are
// DeploymentDocumentFields schemas ordered by collection ULID bytes.
func (deployment InitialDeployment) DraftSpec() (InitialSpec, error) {
	if err := deployment.Validate(); err != nil {
		return InitialSpec{}, err
	}
	collections := slices.Clone(deployment.CollectionIDs)
	slices.SortFunc(collections, func(left, right string) int {
		a, _ := entityid.Parse(left)
		b, _ := entityid.Parse(right)
		return bytes.Compare(a[:], b[:])
	})
	spec := InitialSpec{PlacementDatabaseID: deployment.PlacementDatabaseID, PartitionID: deployment.PartitionID,
		Scope: deployment.Scope, LiveS3: deployment.LiveS3}
	for _, id := range collections {
		catalog, err := InitialCatalog(id, DeploymentDocumentFields)
		if err != nil {
			return InitialSpec{}, err
		}
		spec.Catalogs = append(spec.Catalogs, InitialCatalogInput{CollectionID: id, CanonicalCatalog: catalog.Bytes})
	}
	for index, member := range deployment.Members {
		material, err := host.ManagedMaterialPath(deployment.ManagedRuntimeRoot, deployment.binding(index))
		if err != nil {
			return InitialSpec{}, err
		}
		spec.Members[index] = InitialMember{SeatID: member.SeatID, MemberID: member.MemberID,
			Incarnation: member.Incarnation, ServerName: member.ServerName, FailureDomain: member.FailureDomain,
			MaterialDirectory: material, ReplicationIP: member.PrivateIP, ReplicationPort: deployment.ReplicationPort,
			ClientIP: member.PrivateIP, ClientPort: deployment.ClientPort}
	}
	if spec.Members[0].MemberID > spec.Members[1].MemberID {
		spec.Members[0], spec.Members[1] = spec.Members[1], spec.Members[0]
	}
	return spec, nil
}

// MatchesSpec requires a retained signed spec to be exactly this
// deployment's draft plus its recipient grant.
func (deployment InitialDeployment) MatchesSpec(spec InitialSpec) error {
	draft, err := deployment.DraftSpec()
	if err != nil {
		return err
	}
	unsigned := spec
	unsigned.Recipient = RecipientGrant{}
	want, err := protocol.EncodeJSON(draft)
	if err != nil {
		return err
	}
	got, err := protocol.EncodeJSON(unsigned)
	if err != nil || !bytes.Equal(want, got) {
		return fmt.Errorf("%w: retained material spec differs from the deployment plan", ErrMaterialConflict)
	}
	return nil
}

func SignRecipientGrant(draft InitialSpec, recipient *ecdh.PrivateKey, signer ed25519.PrivateKey,
	expiresAt, now time.Time,
) (InitialSpec, error) {
	if recipient == nil || recipient.Curve() != ecdh.X25519() || len(signer) != ed25519.PrivateKeySize {
		return InitialSpec{}, errors.New("recipient grant needs an X25519 recipient and Ed25519 signer")
	}
	if len(draft.Recipient.PublicKey) != 0 || !draft.Recipient.ExpiresAt.IsZero() || len(draft.Recipient.Signature) != 0 {
		return InitialSpec{}, errors.New("draft material spec already carries a recipient grant")
	}
	spec := draft
	spec.Recipient = RecipientGrant{PublicKey: recipient.PublicKey().Bytes(), ExpiresAt: expiresAt.UTC().Truncate(time.Second)}
	spec.Recipient.Signature = ed25519.Sign(signer, RecipientGrantMessage(spec))
	if err := validateInitialSpec(spec, signer.Public().(ed25519.PublicKey), now); err != nil {
		return InitialSpec{}, err
	}
	return spec, nil
}

// VerifyRecipientGrant checks a retained signed spec against the pinned
// recipient signer without requiring the grant to still be current.
func VerifyRecipientGrant(spec InitialSpec, signer ed25519.PublicKey) error {
	if len(signer) != ed25519.PublicKeySize || len(spec.Recipient.Signature) != ed25519.SignatureSize ||
		!ed25519.Verify(signer, RecipientGrantMessage(spec), spec.Recipient.Signature) {
		return errors.New("retained material spec recipient grant is not signed by the pinned signer")
	}
	return nil
}

func RenderInitialPlacement(receipt PreparationReceipt, deployment InitialDeployment,
	artifact RuntimeArtifact, profile placement.ManagedHostProfile,
) (placement.Intent, error) {
	if err := deployment.Validate(); err != nil {
		return placement.Intent{}, err
	}
	if !strings.EqualFold(receipt.Cell, string(deployment.Region)) || profile.Region != deployment.Region ||
		!lowerHexDigest(artifact.Digest) || !lowerHexDigest(artifact.SourceDigest) {
		return placement.Intent{}, errors.New("placement render inputs differ from the prepared region or artifact")
	}
	spec := receipt.Spec
	if err := deployment.MatchesSpec(spec); err != nil {
		return placement.Intent{}, err
	}
	targetDigest, err := spec.LiveS3.Digest()
	if err != nil {
		return placement.Intent{}, err
	}
	intent := placement.Intent{SchemaVersion: placement.IntentSchemaVersion,
		DatabaseID: spec.PlacementDatabaseID, PartitionID: spec.PartitionID,
		ActiveRegions: []oci.Region{deployment.Region}, Generation: 1,
		CanonicalRoster: placement.CanonicalRoster{ClusterID: spec.Scope.ClusterID, TenantID: spec.Scope.TenantID,
			DatabaseID: spec.Scope.DatabaseID, ShardID: spec.Scope.ShardID,
			Authority: placement.AuthorityReference{Version: 2, Epoch: spec.Scope.Epoch,
				ConfigurationID: receipt.AuthorityConfigurationID, CertificateSHA256: receipt.AuthoritySHA256,
				TrustedKeySHA256: receipt.TrustedKeySHA256}},
		ManagedHostProfiles: []placement.ManagedHostProfile{profile}}
	for _, member := range deployment.Members {
		index := slices.IndexFunc(spec.Members[:], func(seat InitialMember) bool { return seat.SeatID == member.SeatID })
		if index < 0 || spec.Members[index].MemberID != member.MemberID {
			return placement.Intent{}, ErrMaterialConflict
		}
		seat, peer, pins := spec.Members[index], spec.Members[1-index], receipt.Members[index]
		intent.CanonicalRoster.Rows = append(intent.CanonicalRoster.Rows, placement.CanonicalRosterRow{
			Region: deployment.Region, SeatID: seat.SeatID, FailureDomain: seat.FailureDomain,
			MemberID: seat.MemberID, Incarnation: seat.Incarnation,
			TLSLeafSHA256: pins.TLSLeafSHA256, ServerName: seat.ServerName})
		intent.RuntimeManifests = append(intent.RuntimeManifests, placement.RuntimeManifest{
			Region: deployment.Region, SeatID: seat.SeatID,
			ArtifactDigest: artifact.Digest, SourceDigest: artifact.SourceDigest,
			ManagedRuntimeRoot: deployment.ManagedRuntimeRoot, FileSystemUUID: member.FileSystemUUID,
			FileSystemType: ManagedFileSystemType, TrustedKeySHA256: receipt.TrustedKeySHA256,
			ServerCertificateSHA256: pins.Files["server.crt"], ServerPrivateKeySHA256: pins.Files["server.key"],
			ClientCARootsSHA256:                 pins.Files["client-ca.pem"],
			ClientManagedMaterialManifestSHA256: pins.Files["client-managed-manifest.json"],
			SQLSchemaBundleSHA256:               pins.Files[sqlSchemaBundleFileName],
			LiveS3ConfigSHA256:                  pins.Files["signed-v2-s3-config.json"],
			LiveS3TargetSHA256:                  targetDigest,
			LiveS3Credential:                    spec.LiveS3.Credential,
			ReplicationListenAddress:            net.JoinHostPort(seat.ReplicationIP, strconv.Itoa(int(seat.ReplicationPort))),
			ReplicationPeerMemberID:             peer.MemberID,
			ReplicationPeerAddress:              net.JoinHostPort(peer.ReplicationIP, strconv.Itoa(int(peer.ReplicationPort))),
			ReplicationServerCASHA256:           pins.Files["server-ca.pem"],
		})
	}
	if spec.Backup != nil {
		return placement.Intent{}, errors.New("backup-enabled initial material needs a separately reviewed placement")
	}
	if err := VerifyIntentAgainstReceipt(intent, receipt); err != nil {
		return placement.Intent{}, fmt.Errorf("rendered placement differs from prepared material: %w", err)
	}
	return intent, nil
}

func validFileSystemUUID(value string) bool {
	parsed, err := uuid.Parse(value)
	return err == nil && parsed != uuid.Nil() && parsed.String() == value
}

func lowerHexIdentity(value string) bool {
	if len(value) != 32 || strings.Trim(value, "0") == "" {
		return false
	}
	for index := range len(value) {
		if !lowerAlphaNumeric(value[index]) || value[index] > 'f' {
			return false
		}
	}
	return true
}

var initialHostFiles = [...]string{
	"authority.tbca", "trusted-public-key", "server.crt", "server.key",
	"server-ca.pem", "client-ca.pem", "client-chain.pem", "client-private-key.pem",
	"client-api-keys.json", "client-config.json", "client-managed-manifest.json",
	"signed-v2-s3-config.json",
}

func initialHostFileNames(spec InitialSpec) []string {
	names := slices.Clone(initialHostFiles[:])
	if len(spec.SQLTables) > 0 {
		names = append(names, sqlSchemaBundleFileName)
	}
	if spec.Backup != nil {
		names = append(names, backupManifestName, backupConfigName)
	}
	return names
}

// VerifyIntentAgainstReceipt requires an initial placement to use the exact
// material committed in R3. The caller must first authenticate the receipt and
// read its exact OCI object version through PreparationService.Current.
func VerifyIntentAgainstReceipt(intent placement.Intent, receipt PreparationReceipt) error {
	if err := intent.ValidateForAdmission(); err != nil {
		return err
	}
	spec := receipt.Spec
	roster := intent.CanonicalRoster
	liveTargetDigest, liveErr := spec.LiveS3.Digest()
	if intent.Generation != 1 || receipt.Generation != 1 || intent.DatabaseID != spec.PlacementDatabaseID ||
		intent.PartitionID != receipt.PartitionID || intent.PartitionID != spec.PartitionID || len(intent.ActiveRegions) != 1 ||
		!strings.EqualFold(string(intent.ActiveRegions[0]), receipt.Cell) || len(roster.Rows) != 2 ||
		len(intent.RuntimeManifests) != 2 || roster.ClusterID != spec.Scope.ClusterID ||
		roster.TenantID != spec.Scope.TenantID || roster.DatabaseID != spec.Scope.DatabaseID ||
		roster.ShardID != spec.Scope.ShardID || roster.Authority.Version != 2 ||
		roster.Authority.Epoch != spec.Scope.Epoch ||
		roster.Authority.ConfigurationID != receipt.AuthorityConfigurationID ||
		roster.Authority.CertificateSHA256 != receipt.AuthoritySHA256 ||
		roster.Authority.TrustedKeySHA256 != receipt.TrustedKeySHA256 || liveErr != nil {
		return ErrMaterialConflict
	}
	region, err := intent.ActiveRegions[0].OCIRegion()
	if err != nil || spec.LiveS3.Region != region {
		return ErrMaterialConflict
	}
	for _, seat := range spec.Members {
		index := -1
		for candidate, row := range roster.Rows {
			if row.SeatID == seat.SeatID {
				index = candidate
				break
			}
		}
		if index < 0 {
			return ErrMaterialConflict
		}
		row, manifest := roster.Rows[index], intent.RuntimeManifests[index]
		var pins MemberPins
		found := false
		for memberIndex, member := range spec.Members {
			if member.SeatID == seat.SeatID {
				pins = receipt.Members[memberIndex]
				found = true
			}
		}
		files := initialHostFileNames(spec)
		if !found || row.Region != intent.ActiveRegions[0] || row.MemberID != seat.MemberID ||
			row.Incarnation != seat.Incarnation || row.ServerName != seat.ServerName ||
			row.FailureDomain != seat.FailureDomain || row.TLSLeafSHA256 != pins.TLSLeafSHA256 ||
			pins.MemberID != seat.MemberID || len(pins.Files) != len(files) ||
			manifest.SeatID != seat.SeatID || manifest.Region != row.Region ||
			manifest.TrustedKeySHA256 != receipt.TrustedKeySHA256 ||
			manifest.ServerCertificateSHA256 != pins.Files["server.crt"] ||
			manifest.ServerPrivateKeySHA256 != pins.Files["server.key"] ||
			manifest.ClientCARootsSHA256 != pins.Files["client-ca.pem"] ||
			manifest.ClientManagedMaterialManifestSHA256 != pins.Files["client-managed-manifest.json"] ||
			manifest.LiveS3ConfigSHA256 != pins.Files["signed-v2-s3-config.json"] ||
			manifest.SQLSchemaBundleSHA256 != pins.Files[sqlSchemaBundleFileName] ||
			manifest.LiveS3TargetSHA256 != liveTargetDigest ||
			manifest.LiveS3Credential != spec.LiveS3.Credential ||
			!backupRuntimeMatchesSpec(manifest, spec, pins, seat) ||
			manifest.ReplicationServerCASHA256 != pins.Files["server-ca.pem"] ||
			manifest.ReplicationListenAddress != net.JoinHostPort(seat.ReplicationIP, strconv.Itoa(int(seat.ReplicationPort))) {
			return ErrMaterialConflict
		}
		for _, name := range files {
			if !lowerHexDigest(pins.Files[name]) {
				return ErrMaterialConflict
			}
		}
		binding := host.ManagedMemberBinding{Scope: host.MemberScope{
			ClusterID: spec.Scope.ClusterID, TenantID: spec.Scope.TenantID,
			DatabaseID: spec.Scope.DatabaseID, ShardID: spec.Scope.ShardID,
			MemberID: seat.MemberID, Incarnation: seat.Incarnation,
		}, HostAttempt: 1}
		materialPath, err := host.ManagedMaterialPath(manifest.ManagedRuntimeRoot, binding)
		if err != nil || materialPath != seat.MaterialDirectory {
			return ErrMaterialConflict
		}
		peer := spec.Members[0]
		if peer.MemberID == seat.MemberID {
			peer = spec.Members[1]
		}
		if manifest.ReplicationPeerMemberID != peer.MemberID ||
			manifest.ReplicationPeerAddress != net.JoinHostPort(peer.ReplicationIP, strconv.Itoa(int(peer.ReplicationPort))) {
			return ErrMaterialConflict
		}
	}
	if roster.Rows[0].SeatID == roster.Rows[1].SeatID {
		return errors.New("managed placement repeats one prepared seat")
	}
	return nil
}

func backupRuntimeMatchesSpec(manifest placement.RuntimeManifest, spec InitialSpec,
	pins MemberPins, seat InitialMember,
) bool {
	if spec.Backup == nil {
		return manifest.BackupManifestSHA256 == "" && manifest.BackupS3ConfigSHA256 == "" &&
			manifest.BackupS3TargetSHA256 == "" && manifest.BackupS3CredentialSHA256 == "" &&
			manifest.BackupDataKeySHA256 == "" && !manifest.BackupOwner &&
			manifest.BackupS3Credential == (oci.SecretVersionReference{}) &&
			manifest.BackupDataKey == (oci.SecretVersionReference{})
	}
	targetDigest, err := spec.Backup.Target.Digest()
	if err != nil || manifest.BackupManifestSHA256 != pins.Files[backupManifestName] ||
		manifest.BackupS3ConfigSHA256 != pins.Files[backupConfigName] ||
		manifest.BackupS3TargetSHA256 != targetDigest ||
		manifest.BackupS3CredentialSHA256 != spec.Backup.Target.CredentialSHA256 ||
		manifest.BackupDataKeySHA256 != spec.Backup.DataKeySHA256 ||
		manifest.BackupOwner != (seat.MemberID == spec.Backup.OwnerMemberID) {
		return false
	}
	if manifest.BackupOwner {
		return manifest.BackupS3Credential == spec.Backup.Target.Credential &&
			manifest.BackupDataKey == spec.Backup.DataKey
	}
	return manifest.BackupS3Credential == (oci.SecretVersionReference{}) &&
		manifest.BackupDataKey == (oci.SecretVersionReference{})
}

func ManagedMountPath(root string, member ManagedMemberBinding) (string, error) {
	paths, err := runtimePaths(root, ManagedMemberLaunch{Member: member})
	if err != nil {
		return "", err
	}
	return paths.mount, nil
}

// ManagedMaterialPath is the exact host-owned directory for one signed member
// attempt. Preparation uses this path so client configuration cannot redirect
// a host to operator-chosen material.
func ManagedMaterialPath(root string, member ManagedMemberBinding) (string, error) {
	paths, err := runtimePaths(root, ManagedMemberLaunch{Member: member})
	if err != nil {
		return "", err
	}
	return paths.material, nil
}

func runtimePaths(root string, launch ManagedMemberLaunch) (managedRuntimePaths, error) {
	if !filepath.IsAbs(root) || filepath.Clean(root) != root || root == "/" {
		return managedRuntimePaths{}, errors.New("managed runtime root must be a clean absolute directory")
	}
	scope := launch.Member.Scope
	if err := validateManagedMemberBinding(launch.Member); err != nil {
		return managedRuntimePaths{}, err
	}
	sum := sha256.Sum256([]byte(scope.ClusterID + "/" + scope.TenantID + "/" + scope.DatabaseID + "/" +
		strconv.FormatUint(scope.ShardID, 10) + "/" + scope.MemberID + "/" + scope.Incarnation + "/" +
		strconv.FormatUint(launch.Member.HostAttempt, 10)))
	memberDir := filepath.Join(root, hex.EncodeToString(sum[:16]))
	paths := managedRuntimePaths{
		memberDir:  memberDir,
		mount:      filepath.Join(memberDir, "volume"),
		material:   filepath.Join(memberDir, "material"),
		socket:     filepath.Join(memberDir, "control", "member.sock"),
		nativeRoot: filepath.Join(memberDir, "native-root.sock"),
	}
	if len(paths.socket) >= 108 || len(paths.nativeRoot) >= 108 {
		return managedRuntimePaths{}, errors.New("managed socket path exceeds Unix limit")
	}
	return paths, nil
}

func validateManagedMemberBinding(binding ManagedMemberBinding) error {
	scope := binding.Scope
	if !lowerHexIdentity(scope.ClusterID) || !lowerHexIdentity(scope.Incarnation) ||
		!canonicalMemberID(scope.TenantID) || !canonicalMemberID(scope.DatabaseID) ||
		!canonicalMemberID(scope.MemberID) || scope.ShardID == 0 || binding.HostAttempt == 0 {
		return errors.New("managed member identity is invalid")
	}
	return nil
}

func (manifest RuntimeManifest) Validate() error {

	if !knownRegion(manifest.Region) || !entityid.Valid(manifest.SeatID) ||
		!validLowerSHA256Digest(manifest.ArtifactDigest) || !validLowerSHA256Digest(manifest.SourceDigest) ||
		!filepath.IsAbs(manifest.ManagedRuntimeRoot) || filepath.Clean(manifest.ManagedRuntimeRoot) != manifest.ManagedRuntimeRoot ||
		manifest.ManagedRuntimeRoot == "/" || len(manifest.ManagedRuntimeRoot) > 54 ||
		!validFilesystemUUID(manifest.FileSystemUUID) ||
		manifest.FileSystemType != "ext4" && manifest.FileSystemType != "xfs" ||
		!validLowerSHA256Digest(manifest.TrustedKeySHA256) ||
		!validLowerSHA256Digest(manifest.ServerCertificateSHA256) ||
		!validLowerSHA256Digest(manifest.ServerPrivateKeySHA256) ||
		!validLowerSHA256Digest(manifest.ClientCARootsSHA256) ||
		!validPrivateIPv4Endpoint(manifest.ReplicationListenAddress) {
		return fmt.Errorf("%w: incomplete runtime manifest", ErrInvalidIntent)
	}
	peer := manifest.ReplicationPeerMemberID != "" || manifest.ReplicationPeerAddress != "" || manifest.ReplicationServerCASHA256 != ""
	if peer && (!entityid.Valid(manifest.ReplicationPeerMemberID) ||
		!validPrivateIPv4Endpoint(manifest.ReplicationPeerAddress) ||
		!validLowerSHA256Digest(manifest.ReplicationServerCASHA256)) {
		return fmt.Errorf("%w: incomplete runtime peer triple", ErrInvalidIntent)
	}
	if !validLowerSHA256Digest(manifest.ClientManagedMaterialManifestSHA256) || !peer {
		return fmt.Errorf("%w: schema-5 managed HTTPS requires a pinned client material manifest and outbound peer", ErrInvalidIntent)
	}
	if !validLowerSHA256Digest(manifest.LiveS3ConfigSHA256) ||
		!validLowerSHA256Digest(manifest.LiveS3TargetSHA256) || manifest.LiveS3Credential.Validate() != nil {
		return fmt.Errorf("%w: managed ObjectDurable target or credential pin is incomplete", ErrInvalidIntent)
	}
	if manifest.BackupManifestSHA256 != "" {
		if !validLowerSHA256Digest(manifest.BackupManifestSHA256) ||
			!validLowerSHA256Digest(manifest.BackupS3ConfigSHA256) ||
			!validLowerSHA256Digest(manifest.BackupS3TargetSHA256) ||
			!validLowerSHA256Digest(manifest.BackupS3CredentialSHA256) ||
			!validLowerSHA256Digest(manifest.BackupDataKeySHA256) ||
			manifest.BackupS3TargetSHA256 == manifest.LiveS3TargetSHA256 ||
			manifest.BackupOwner && (manifest.BackupS3Credential.Validate() != nil ||
				manifest.BackupDataKey.Validate() != nil ||
				manifest.BackupS3Credential.SecretOCID == manifest.LiveS3Credential.SecretOCID ||
				manifest.BackupS3Credential.SecretOCID == manifest.BackupDataKey.SecretOCID) ||
			!manifest.BackupOwner && (manifest.BackupS3Credential != (oci.SecretVersionReference{}) ||
				manifest.BackupDataKey != (oci.SecretVersionReference{})) {
			return fmt.Errorf("%w: managed backup material pins are incomplete", ErrInvalidIntent)
		}
	} else if manifest.BackupS3ConfigSHA256 != "" || manifest.BackupS3TargetSHA256 != "" ||
		manifest.BackupS3CredentialSHA256 != "" || manifest.BackupDataKeySHA256 != "" ||
		manifest.BackupOwner || manifest.BackupS3Credential != (oci.SecretVersionReference{}) ||
		manifest.BackupDataKey != (oci.SecretVersionReference{}) {
		return fmt.Errorf("%w: partial managed backup material pins", ErrInvalidIntent)
	}
	if manifest.SQLSchemaBundleSHA256 != "" && !validLowerSHA256Digest(manifest.SQLSchemaBundleSHA256) {
		return fmt.Errorf("%w: invalid SQL schema bundle pin", ErrInvalidIntent)
	}
	return nil
}

func (profile ManagedHostProfile) Validate() error {
	if !knownRegion(profile.Region) || !validComputeShape(profile.Compute.Shape) ||
		profile.Compute.WholeOCPUs == 0 || profile.Compute.MemoryInGBs == 0 {
		return fmt.Errorf("%w: managed profile region or compute tuple", ErrInvalidIntent)
	}
	values := [...]uint64{
		profile.ProcessMemoryBytes, profile.MemoryHeadroomBytes, profile.CgroupMemoryMaxBytes,
		profile.SystemReserveBytes, profile.AllocatableMemoryBytes,
	}
	for _, value := range values {
		if value == 0 || value > maxManagedMemoryByteValue || value%managedMemoryPageBytes != 0 {
			return fmt.Errorf("%w: memory limits must be positive, signed-range, page-aligned byte values", ErrInvalidIntent)
		}
	}
	minimumHeadroom := max(managedMemoryGiB, profile.ProcessMemoryBytes/4)
	// MemoryInGBs is uint32, so this exact multiplication stays below 2^62.
	// GiB is the conservative upper bound whether the SDK's GB means decimal
	// or binary units; the host still verifies actual guest capacity.
	nominalMemoryBytes := uint64(profile.Compute.MemoryInGBs) * managedMemoryGiB
	if profile.ProcessMemoryBytes < 4*managedMemoryGiB || profile.MemoryHeadroomBytes < minimumHeadroom ||
		profile.MemoryHeadroomBytes >= profile.ProcessMemoryBytes ||
		profile.ProcessMemoryBytes > profile.CgroupMemoryMaxBytes ||
		profile.CgroupMemoryMaxBytes > profile.AllocatableMemoryBytes ||
		profile.SystemReserveBytes > maxManagedMemoryByteValue-profile.AllocatableMemoryBytes ||
		profile.AllocatableMemoryBytes > nominalMemoryBytes ||
		profile.SystemReserveBytes > nominalMemoryBytes-profile.AllocatableMemoryBytes {
		return fmt.Errorf("%w: managed process, headroom, cgroup, allocatable memory and reserve bounds", ErrInvalidIntent)
	}
	return nil
}

func (intent Intent) Validate() error {
	if intent.SchemaVersion != IntentSchemaVersion ||
		!entityid.Valid(intent.DatabaseID) ||
		!entityid.Valid(intent.PartitionID) || intent.Generation == 0 ||
		len(intent.ActiveRegions) < 1 || len(intent.ActiveRegions) > len(regionsInOrder) {
		return fmt.Errorf("%w: schema, identity, generation or region count", ErrInvalidIntent)
	}
	for index, region := range intent.ActiveRegions {
		if !knownRegion(region) {
			return fmt.Errorf("%w: unsupported region %q", ErrInvalidIntent, region)
		}
		if slices.Contains(intent.ActiveRegions[:index], region) {
			return fmt.Errorf("%w: repeated region %q", ErrInvalidIntent, region)
		}
	}
	if !canonicalRegions(intent.ActiveRegions) || len(intent.ManagedHostProfiles) != len(intent.ActiveRegions) {
		return fmt.Errorf("%w: managed profiles must exactly cover canonically ordered selected regions", ErrInvalidIntent)
	}
	for index, profile := range intent.ManagedHostProfiles {
		if profile.Region != intent.ActiveRegions[index] {
			return fmt.Errorf("%w: managed profiles are missing, foreign or out of canonical order", ErrInvalidIntent)
		}
		if err := profile.Validate(); err != nil {
			return err
		}
	}
	if err := intent.CanonicalRoster.Validate(intent.ActiveRegions); err != nil {
		return err
	}
	if len(intent.RuntimeManifests) != len(intent.CanonicalRoster.Rows) {
		return fmt.Errorf("%w: runtime manifests must cover every canonical roster seat", ErrInvalidIntent)
	}
	uuids := make(map[string]struct{}, len(intent.RuntimeManifests))
	for index, manifest := range intent.RuntimeManifests {
		row := intent.CanonicalRoster.Rows[index]
		if err := manifest.Validate(); err != nil {
			return err
		}
		if manifest.Region != row.Region || manifest.SeatID != row.SeatID ||
			manifest.TrustedKeySHA256 != intent.CanonicalRoster.Authority.TrustedKeySHA256 ||
			manifest.ReplicationPeerMemberID == row.MemberID {
			return fmt.Errorf("%w: runtime manifest does not match canonical roster seat", ErrInvalidIntent)
		}
		if manifest.ReplicationPeerMemberID != "" && !slices.ContainsFunc(intent.CanonicalRoster.Rows, func(peer CanonicalRosterRow) bool {
			return peer.MemberID == manifest.ReplicationPeerMemberID
		}) {
			return fmt.Errorf("%w: runtime peer is outside the signed roster", ErrInvalidIntent)
		}
		if _, exists := uuids[manifest.FileSystemUUID]; exists {
			return fmt.Errorf("%w: duplicate runtime filesystem UUID", ErrInvalidIntent)
		}
		uuids[manifest.FileSystemUUID] = struct{}{}
	}
	return nil
}

// ValidateForAdmission limits newly signed managed placements to schema 5.
// Only the current schema is accepted.
func (intent Intent) ValidateForAdmission() error {
	if intent.SchemaVersion != IntentSchemaVersion {
		return fmt.Errorf("%w: schema %d is historical and cannot authorize a new managed placement", ErrInvalidIntent, intent.SchemaVersion)
	}
	return intent.Validate()
}

func (roster CanonicalRoster) isZero() bool {
	return roster.ClusterID == "" && roster.TenantID == "" && roster.DatabaseID == "" &&
		roster.ShardID == 0 && roster.Authority == (AuthorityReference{}) && len(roster.Rows) == 0
}

func (roster CanonicalRoster) Validate(activeRegions []oci.Region) error {

	if !lowerHex(roster.ClusterID, 32) || allZeroHex(roster.ClusterID) ||
		!entityid.Valid(roster.TenantID) || !entityid.Valid(roster.DatabaseID) ||
		roster.ShardID == 0 || roster.Authority.Validate() != nil ||
		len(roster.Rows) != len(activeRegions)*2 {
		return fmt.Errorf("%w: canonical roster shared scope or row count", ErrInvalidIntent)
	}

	memberIDs := make(map[string]struct{}, len(roster.Rows))
	tlsLeafHashes := make(map[string]struct{}, len(roster.Rows))
	serverNames := make(map[string]struct{}, len(roster.Rows))
	failureDomains := make(map[oci.Region]string, len(activeRegions))
	for index, row := range roster.Rows {
		region := activeRegions[index/2]
		seatID := permanentMember(region)
		if index%2 == 1 {
			seatID = elasticMember(region)
		}
		if row.Region != region || row.SeatID != seatID || !validFailureDomain(row.FailureDomain) ||
			!entityid.Valid(row.MemberID) || !lowerHex(row.Incarnation, 32) || allZeroHex(row.Incarnation) ||
			!validLowerSHA256Digest(row.TLSLeafSHA256) || !validServerName(row.ServerName) {
			return fmt.Errorf("%w: invalid or noncanonical row %d in TerraBase member roster", ErrInvalidIntent, index)
		}
		if _, exists := memberIDs[row.MemberID]; exists {
			return fmt.Errorf("%w: repeated TerraBase member ID %q", ErrInvalidIntent, row.MemberID)
		}
		if _, exists := tlsLeafHashes[row.TLSLeafSHA256]; exists {
			return fmt.Errorf("%w: repeated TerraBase TLS leaf hash", ErrInvalidIntent)
		}
		if _, exists := serverNames[row.ServerName]; exists {
			return fmt.Errorf("%w: repeated TerraBase member server name %q", ErrInvalidIntent, row.ServerName)
		}
		if index%2 == 0 {
			failureDomains[region] = row.FailureDomain
		} else if failureDomains[region] == row.FailureDomain {
			return fmt.Errorf("%w: TerraBase members in region %s share a failure domain", ErrInvalidIntent, region)
		}
		memberIDs[row.MemberID] = struct{}{}
		tlsLeafHashes[row.TLSLeafSHA256] = struct{}{}
		serverNames[row.ServerName] = struct{}{}
	}
	return nil
}

func (authority AuthorityReference) Validate() error {
	if authority.Version != 2 || authority.Epoch == 0 ||
		!validLowerSHA256Digest(authority.ConfigurationID) || allZeroHex(authority.ConfigurationID) ||
		!validLowerSHA256Digest(authority.CertificateSHA256) || !validLowerSHA256Digest(authority.TrustedKeySHA256) {
		return fmt.Errorf("%w: invalid TerraBase authority reference", ErrInvalidIntent)
	}
	return nil
}

func RegionSeatIDs(region oci.Region) ([2]string, error) {
	if !knownRegion(region) {
		return [2]string{}, fmt.Errorf("%w: unsupported region %q", ErrInvalidIntent, region)
	}
	return [2]string{permanentMember(region), elasticMember(region)}, nil
}

func permanentMember(region oci.Region) string {
	if !slices.Contains(regionsInOrder, region) {
		return ""
	}
	return entityid.Derive("placement-seat", string(region), "1")
}

func elasticMember(region oci.Region) string {
	return entityid.Derive("placement-seat", string(region), "2")
}
